-- ScoutLink OC database setup: every migration in order.
-- Generated by `npm run db:bundle` from supabase/migrations. Don't edit by hand.
--
-- Paste into the Supabase SQL editor of a NEW project and run once.
-- For an existing project, run only the migrations it hasn't had yet.

-- ===========================================================================
-- 20261111000100_foundation.sql
-- ===========================================================================

-- ScoutLink OC: foundation
-- Shared schemas, types, settings, rate limiting and audit logging.
--
-- Security model: the browser only ever holds the publishable key. Row Level
-- Security (RLS) protects every table in `public`. Privileged changes go through
-- SECURITY DEFINER functions that re-check the caller's verified roles. Helper
-- functions live in `private`, which PostgREST does not expose.

-- ---------------------------------------------------------------------------
-- Schemas
-- ---------------------------------------------------------------------------
create schema if not exists private;
revoke all on schema private from public;
-- RLS policies call helpers in `private`, so the API role needs USAGE (not exposure).
grant usage on schema private to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Types
-- ---------------------------------------------------------------------------
create type public.account_state as enum ('pending_verification', 'active', 'suspended', 'deactivated');

create type public.app_role as enum (
  'platform_admin',
  'council_admin',
  'service_unit_coordinator',
  'troop_leader',
  'adult_volunteer',
  'girl_member',
  'guardian'
);

create type public.role_scope as enum ('platform', 'council', 'service_unit', 'troop');
create type public.girl_scout_level as enum ('daisy', 'brownie', 'junior', 'cadette', 'senior', 'ambassador');
create type public.oc_region as enum ('north', 'central', 'south', 'coastal', 'west');
create type public.affiliation_status as enum ('requested', 'approved', 'rejected', 'ended');
create type public.verification_status as enum ('pending', 'approved', 'rejected', 'withdrawn');
create type public.data_source as enum ('fictional_demo', 'council_record', 'self_reported');
create type public.collaboration_status as enum ('open', 'limited', 'closed');
create type public.directory_visibility as enum ('council_members', 'public_listing', 'hidden');

-- ---------------------------------------------------------------------------
-- Platform settings (not exposed through the API)
-- ---------------------------------------------------------------------------
create table private.settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

insert into private.settings (key, value) values
  -- Youth accounts stay off until the council approves consent and supervision procedures.
  ('youth_access_enabled', 'false'::jsonb),
  -- Version of the Terms of use and Privacy policy users agree to during onboarding.
  ('policy_version', '"2026-11-draft"'::jsonb);

create function private.setting(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select value from private.settings where key = p_key;
$$;

-- ---------------------------------------------------------------------------
-- updated_at trigger
-- ---------------------------------------------------------------------------
create function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Rate limiting
-- ---------------------------------------------------------------------------
create table private.rate_limits (
  bucket text not null,
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (bucket, window_start)
);

-- Counts one hit in a fixed window and raises 'rate_limited' when the limit is exceeded.
create function private.check_rate_limit(p_bucket text, p_max integer, p_window interval)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_window timestamptz := date_bin(p_window, now(), timestamptz '2000-01-01 00:00:00+00');
  v_hits integer;
begin
  insert into private.rate_limits as r (bucket, window_start, hits)
  values (p_bucket, v_window, 1)
  on conflict (bucket, window_start) do update set hits = r.hits + 1
  returning hits into v_hits;

  if v_hits > p_max then
    raise exception 'rate_limited' using errcode = 'P0001', hint = 'Too many attempts. Please wait and try again.';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Audit log (append-only)
-- ---------------------------------------------------------------------------
create table public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid,
  action text not null check (char_length(action) <= 80),
  target_type text check (char_length(target_type) <= 40),
  target_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index audit_logs_created_at_idx on public.audit_logs (created_at desc);
create index audit_logs_target_idx on public.audit_logs (target_type, target_id);

-- Never pass passwords, tokens or message bodies in p_metadata.
create function private.audit(p_action text, p_target_type text, p_target_id uuid, p_metadata jsonb default '{}'::jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.audit_logs (actor_id, action, target_type, target_id, metadata)
  values ((select auth.uid()), p_action, p_target_type, p_target_id, coalesce(p_metadata, '{}'::jsonb));
$$;

alter table public.audit_logs enable row level security;
revoke all on table public.audit_logs from anon, authenticated;

-- Lock down every helper; RLS-facing helpers are re-granted where they're defined.
revoke all on all functions in schema private from public, anon, authenticated;

-- ===========================================================================
-- 20261111000200_identity.sql
-- ===========================================================================

-- ScoutLink OC: identity, organizations, roles and verification
--
-- Roles come only from `role_assignments`, which no user can write directly.
-- A person is "active" only after an administrator verifies them; until then
-- they can read their own account and nothing else.

-- ---------------------------------------------------------------------------
-- Organizations
-- ---------------------------------------------------------------------------
create table public.service_units (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  code text check (char_length(code) <= 20),
  region public.oc_region not null,
  description text not null default '' check (char_length(description) <= 2000),
  founded_year integer check (founded_year between 1912 and 2100),
  founded_year_source public.data_source,
  visibility public.directory_visibility not null default 'council_members',
  is_demo boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index service_units_name_active_idx on public.service_units (lower(name)) where archived_at is null;

create table public.troops (
  id uuid primary key default gen_random_uuid(),
  number text not null check (number ~ '^[0-9A-Za-z-]{1,12}$'),
  service_unit_id uuid not null references public.service_units (id) on delete restrict,
  introduction text not null default '' check (char_length(introduction) <= 2000),
  approx_size integer check (approx_size between 0 and 500),
  size_source public.data_source,
  size_as_of date,
  founded_year integer check (founded_year between 1912 and 2100),
  founded_year_source public.data_source,
  collaboration_status public.collaboration_status not null default 'open',
  visibility public.directory_visibility not null default 'council_members',
  is_demo boolean not null default false,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Official-looking numbers must say where they came from.
  constraint troops_size_provenance check (approx_size is null or size_source is not null),
  constraint troops_founded_provenance check (founded_year is null or founded_year_source is not null)
);

create unique index troops_number_active_idx on public.troops (number) where archived_at is null;
create index troops_service_unit_idx on public.troops (service_unit_id);

-- A service unit's levels are derived from its troops; never stored on the service unit.
create table public.troop_levels (
  troop_id uuid not null references public.troops (id) on delete cascade,
  level public.girl_scout_level not null,
  primary key (troop_id, level)
);

-- ---------------------------------------------------------------------------
-- People
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default '' check (char_length(display_name) <= 80),
  bio text not null default '' check (char_length(bio) <= 600),
  interests text[] not null default '{}' check (cardinality(interests) <= 12),
  general_location text not null default '' check (char_length(general_location) <= 80),
  account_state public.account_state not null default 'pending_verification',
  state_reason text check (char_length(state_reason) <= 500),
  deletion_requested_at timestamptz,
  deletion_reason text check (char_length(deletion_reason) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.role_assignments (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  role public.app_role not null,
  scope_type public.role_scope not null,
  scope_id uuid,
  granted_by uuid references public.profiles (id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_at timestamptz,
  revoked_by uuid references public.profiles (id) on delete set null,
  constraint role_assignments_scope_matches_role check (
    (role = 'platform_admin' and scope_type = 'platform' and scope_id is null)
    or (role = 'council_admin' and scope_type = 'council' and scope_id is null)
    or (role = 'guardian' and scope_type = 'council' and scope_id is null)
    or (role = 'service_unit_coordinator' and scope_type = 'service_unit' and scope_id is not null)
    or (role in ('troop_leader', 'adult_volunteer', 'girl_member') and scope_type = 'troop' and scope_id is not null)
  )
);

create unique index role_assignments_active_idx
  on public.role_assignments (profile_id, role, scope_type, coalesce(scope_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where revoked_at is null;
create index role_assignments_profile_idx on public.role_assignments (profile_id) where revoked_at is null;

create table public.verification_requests (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  requested_role public.app_role not null,
  service_unit_id uuid not null references public.service_units (id) on delete restrict,
  troop_id uuid references public.troops (id) on delete restrict,
  note text not null default '' check (char_length(note) <= 1000),
  status public.verification_status not null default 'pending',
  decided_by uuid references public.profiles (id) on delete set null,
  decided_at timestamptz,
  decision_note text check (char_length(decision_note) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index verification_requests_one_pending_idx on public.verification_requests (profile_id) where status = 'pending';
create index verification_requests_status_idx on public.verification_requests (status, created_at);

create table public.troop_affiliations (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  troop_id uuid not null references public.troops (id) on delete cascade,
  status public.affiliation_status not null default 'requested',
  verification_request_id uuid references public.verification_requests (id) on delete set null,
  decided_by uuid references public.profiles (id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index troop_affiliations_current_idx on public.troop_affiliations (profile_id, troop_id) where status in ('requested', 'approved');
create index troop_affiliations_troop_idx on public.troop_affiliations (troop_id, status);

create table public.service_unit_affiliations (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  service_unit_id uuid not null references public.service_units (id) on delete cascade,
  status public.affiliation_status not null default 'requested',
  verification_request_id uuid references public.verification_requests (id) on delete set null,
  decided_by uuid references public.profiles (id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index service_unit_affiliations_current_idx on public.service_unit_affiliations (profile_id, service_unit_id) where status in ('requested', 'approved');
create index service_unit_affiliations_su_idx on public.service_unit_affiliations (service_unit_id, status);

create table public.user_consents (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  -- Youth and guardian consent types are deliberately absent until procedures are approved.
  consent_type text not null check (consent_type in ('terms_and_privacy')),
  policy_version text not null check (char_length(policy_version) <= 40),
  granted_at timestamptz not null default now(),
  withdrawn_at timestamptz,
  unique (profile_id, consent_type, policy_version)
);

-- Future, gated capability: no policies, so nobody can read or write it through the API.
create table public.guardian_relationships (
  id uuid primary key default gen_random_uuid(),
  guardian_id uuid not null references public.profiles (id) on delete cascade,
  member_id uuid not null references public.profiles (id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'verified', 'ended')),
  verified_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  unique (guardian_id, member_id)
);

-- Public contact form. Inserted only through submit_contact_message().
create table public.contact_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 80),
  email text not null check (char_length(email) <= 254),
  topic text not null check (topic in ('general', 'pilot', 'accessibility', 'safety', 'bug')),
  message text not null check (char_length(message) between 20 and 2000),
  handled_at timestamptz,
  handled_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

-- updated_at triggers
create trigger service_units_updated_at before update on public.service_units for each row execute function private.set_updated_at();
create trigger troops_updated_at before update on public.troops for each row execute function private.set_updated_at();
create trigger profiles_updated_at before update on public.profiles for each row execute function private.set_updated_at();
create trigger verification_requests_updated_at before update on public.verification_requests for each row execute function private.set_updated_at();
create trigger troop_affiliations_updated_at before update on public.troop_affiliations for each row execute function private.set_updated_at();
create trigger service_unit_affiliations_updated_at before update on public.service_unit_affiliations for each row execute function private.set_updated_at();

-- Interest tags are short plain-text labels.
create function private.validate_profile()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.display_name := btrim(new.display_name);
  new.general_location := btrim(new.general_location);
  if exists (select 1 from unnest(new.interests) as tag where char_length(btrim(tag)) not between 1 and 40) then
    raise exception 'invalid_interests' using errcode = 'P0001', hint = 'Each interest must be 1 to 40 characters.';
  end if;
  return new;
end;
$$;

create trigger profiles_validate before insert or update on public.profiles for each row execute function private.validate_profile();

-- ---------------------------------------------------------------------------
-- New users get a pending profile automatically.
-- ---------------------------------------------------------------------------
create function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, left(btrim(coalesce(new.raw_user_meta_data ->> 'display_name', '')), 80))
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

-- ---------------------------------------------------------------------------
-- Authorization helpers (used by RLS policies)
-- ---------------------------------------------------------------------------
create function private.current_account_state()
returns public.account_state
language sql
stable
security definer
set search_path = ''
as $$
  select account_state from public.profiles where id = (select auth.uid());
$$;

create function private.is_active()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select private.current_account_state()) = 'active', false);
$$;

-- True when the caller is active and holds the role (any scope).
create function private.has_role(p_role public.app_role)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select private.is_active()) and exists (
    select 1 from public.role_assignments
    where profile_id = (select auth.uid()) and role = p_role and revoked_at is null
  );
$$;

-- True when the caller is active and holds the role for this exact scope.
create function private.has_scoped_role(p_role public.app_role, p_scope_type public.role_scope, p_scope_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select private.is_active()) and exists (
    select 1 from public.role_assignments
    where profile_id = (select auth.uid())
      and role = p_role
      and scope_type = p_scope_type
      and scope_id is not distinct from p_scope_id
      and revoked_at is null
  );
$$;

create function private.is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.has_role('platform_admin');
$$;

-- Administrators who can verify volunteers and manage organization records.
create function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.has_role('platform_admin') or private.has_role('council_admin');
$$;

-- Nothing in `private` is callable by API roles except these read-only helpers used by policies.
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function
  private.current_account_state(),
  private.is_active(),
  private.has_role(public.app_role),
  private.has_scoped_role(public.app_role, public.role_scope, uuid),
  private.is_platform_admin(),
  private.is_admin()
to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.service_units enable row level security;
alter table public.troops enable row level security;
alter table public.troop_levels enable row level security;
alter table public.profiles enable row level security;
alter table public.role_assignments enable row level security;
alter table public.verification_requests enable row level security;
alter table public.troop_affiliations enable row level security;
alter table public.service_unit_affiliations enable row level security;
alter table public.user_consents enable row level security;
alter table public.guardian_relationships enable row level security;
alter table public.contact_messages enable row level security;

-- Start from nothing: Supabase grants broad table privileges by default.
revoke all on table
  public.service_units, public.troops, public.troop_levels, public.profiles, public.role_assignments,
  public.verification_requests, public.troop_affiliations, public.service_unit_affiliations,
  public.user_consents, public.guardian_relationships, public.contact_messages
from anon, authenticated;

-- Organizations: verified members can read non-hidden records; admins can read everything.
grant select on public.service_units, public.troops, public.troop_levels to authenticated;

create policy "verified members read visible service units" on public.service_units
  for select to authenticated
  using (((select private.is_active()) and archived_at is null and visibility <> 'hidden') or (select private.is_admin()));

create policy "verified members read visible troops" on public.troops
  for select to authenticated
  using (((select private.is_active()) and archived_at is null and visibility <> 'hidden') or (select private.is_admin()));

create policy "verified members read troop levels" on public.troop_levels
  for select to authenticated
  using (exists (select 1 from public.troops t where t.id = troop_id));

-- Profiles: you can read your own; admins can read all. You can edit only a few columns.
grant select on public.profiles to authenticated;
grant update (display_name, bio, interests, general_location) on public.profiles to authenticated;

create policy "read own profile" on public.profiles
  for select to authenticated
  using (id = (select auth.uid()));

create policy "admins read profiles" on public.profiles
  for select to authenticated
  using ((select private.is_admin()));

create policy "edit own profile while pending or active" on public.profiles
  for update to authenticated
  using (id = (select auth.uid()) and (select private.current_account_state()) in ('pending_verification', 'active'))
  with check (id = (select auth.uid()));

-- Roles, requests, affiliations and consents: read your own; admins read all. No direct writes.
grant select on public.role_assignments, public.verification_requests, public.troop_affiliations,
  public.service_unit_affiliations, public.user_consents to authenticated;

create policy "read own roles" on public.role_assignments
  for select to authenticated using (profile_id = (select auth.uid()) or (select private.is_admin()));

create policy "read own verification requests" on public.verification_requests
  for select to authenticated using (profile_id = (select auth.uid()) or (select private.is_admin()));

create policy "read own troop affiliations" on public.troop_affiliations
  for select to authenticated using (profile_id = (select auth.uid()) or (select private.is_admin()));

create policy "read own service unit affiliations" on public.service_unit_affiliations
  for select to authenticated using (profile_id = (select auth.uid()) or (select private.is_admin()));

create policy "read own consents" on public.user_consents
  for select to authenticated using (profile_id = (select auth.uid()));

-- Audit logs and contact messages: administrators only.
grant select on public.audit_logs, public.contact_messages to authenticated;

create policy "admins read audit logs" on public.audit_logs
  for select to authenticated using ((select private.is_admin()));

create policy "admins read contact messages" on public.contact_messages
  for select to authenticated using ((select private.is_admin()));

-- guardian_relationships: RLS on, no grants, no policies (future gated capability).

-- ===========================================================================
-- 20261111000300_identity_functions.sql
-- ===========================================================================

-- ScoutLink OC: account, verification and administration functions
--
-- These SECURITY DEFINER functions are the only way to change roles, account
-- states, affiliations and verification requests. Each one checks the caller's
-- identity and verified roles itself; none trusts values sent by the browser.
-- Errors use short codes in the message (for example 'forbidden') that the app
-- translates into plain language.

-- ---------------------------------------------------------------------------
-- Your own account
-- ---------------------------------------------------------------------------

-- Everything the signed-in person may see about their own account, in one call.
create function public.get_my_account()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;

  select jsonb_build_object(
    'id', p.id,
    'email', u.email,
    'display_name', p.display_name,
    'bio', p.bio,
    'interests', to_jsonb(p.interests),
    'general_location', p.general_location,
    'account_state', p.account_state,
    'state_reason', p.state_reason,
    'deletion_requested_at', p.deletion_requested_at,
    'created_at', p.created_at,
    'policy_version', private.setting('policy_version') #>> '{}',
    'has_current_consent', exists (
      select 1 from public.user_consents c
      where c.profile_id = p.id and c.consent_type = 'terms_and_privacy'
        and c.policy_version = private.setting('policy_version') #>> '{}' and c.withdrawn_at is null
    ),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'role', r.role,
        'scope_type', r.scope_type,
        'scope_id', r.scope_id,
        'scope_name', case r.scope_type
          when 'troop' then (select 'Troop ' || t.number from public.troops t where t.id = r.scope_id)
          when 'service_unit' then (select s.name from public.service_units s where s.id = r.scope_id)
          when 'council' then 'Council'
          else 'Platform'
        end,
        'granted_at', r.granted_at
      ) order by r.granted_at)
      from public.role_assignments r
      where r.profile_id = p.id and r.revoked_at is null
    ), '[]'::jsonb),
    'latest_request', (
      select jsonb_build_object(
        'id', v.id,
        'requested_role', v.requested_role,
        'service_unit_id', v.service_unit_id,
        'service_unit_name', s.name,
        'troop_id', v.troop_id,
        'troop_number', t.number,
        'note', v.note,
        'status', v.status,
        'decision_note', v.decision_note,
        'created_at', v.created_at,
        'decided_at', v.decided_at
      )
      from public.verification_requests v
      join public.service_units s on s.id = v.service_unit_id
      left join public.troops t on t.id = v.troop_id
      where v.profile_id = p.id
      order by v.created_at desc
      limit 1
    )
  )
  into v_result
  from public.profiles p
  join auth.users u on u.id = p.id
  where p.id = v_uid;

  if v_result is null then
    raise exception 'profile_missing' using errcode = 'P0001';
  end if;
  return v_result;
end;
$$;

-- Service units and troops a person can choose during onboarding (names and numbers only).
create function public.list_affiliation_options()
returns table (service_unit_id uuid, service_unit_name text, region public.oc_region, troop_id uuid, troop_number text)
language sql
stable
security definer
set search_path = ''
as $$
  select s.id, s.name, s.region, t.id, t.number
  from public.service_units s
  left join public.troops t
    on t.service_unit_id = s.id and t.archived_at is null and t.visibility <> 'hidden'
  where (select auth.uid()) is not null
    and s.archived_at is null and s.visibility <> 'hidden'
  order by s.name, t.number;
$$;

-- Onboarding: asks to be verified for a role. Choosing a role here grants nothing.
create function public.submit_onboarding(
  p_display_name text,
  p_requested_role public.app_role,
  p_service_unit_id uuid,
  p_troop_id uuid,
  p_interests text[],
  p_note text,
  p_policy_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_state public.account_state;
  v_name text := btrim(coalesce(p_display_name, ''));
  v_note text := btrim(coalesce(p_note, ''));
  v_interests text[] := coalesce((select array_agg(btrim(x)) from unnest(coalesce(p_interests, '{}')) as x where btrim(x) <> ''), '{}');
  v_request_id uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;

  select account_state into v_state from public.profiles where id = v_uid;
  if v_state is null then
    raise exception 'profile_missing' using errcode = 'P0001';
  elsif v_state not in ('pending_verification', 'active') then
    raise exception 'account_not_eligible' using errcode = 'P0001';
  end if;

  perform private.check_rate_limit('onboarding:' || v_uid::text, 5, interval '1 day');

  if char_length(v_name) not between 2 and 80 then
    raise exception 'invalid_display_name' using errcode = 'P0001';
  end if;
  if p_requested_role not in ('troop_leader', 'adult_volunteer', 'service_unit_coordinator') then
    raise exception 'role_not_requestable' using errcode = 'P0001';
  end if;
  if cardinality(v_interests) > 12 or exists (select 1 from unnest(v_interests) x where char_length(x) > 40) then
    raise exception 'invalid_interests' using errcode = 'P0001';
  end if;
  if char_length(v_note) > 1000 then
    raise exception 'invalid_note' using errcode = 'P0001';
  end if;
  if p_policy_version is distinct from (private.setting('policy_version') #>> '{}') then
    raise exception 'policy_version_mismatch' using errcode = 'P0001';
  end if;

  if not exists (
    select 1 from public.service_units
    where id = p_service_unit_id and archived_at is null and visibility <> 'hidden'
  ) then
    raise exception 'invalid_service_unit' using errcode = 'P0001';
  end if;

  if p_requested_role in ('troop_leader', 'adult_volunteer') and p_troop_id is null then
    raise exception 'troop_required' using errcode = 'P0001';
  end if;
  if p_troop_id is not null and not exists (
    select 1 from public.troops
    where id = p_troop_id and service_unit_id = p_service_unit_id and archived_at is null and visibility <> 'hidden'
  ) then
    raise exception 'invalid_troop' using errcode = 'P0001';
  end if;

  if exists (select 1 from public.verification_requests where profile_id = v_uid and status = 'pending') then
    raise exception 'request_pending' using errcode = 'P0001';
  end if;

  update public.profiles set display_name = v_name, interests = v_interests where id = v_uid;

  insert into public.user_consents (profile_id, consent_type, policy_version)
  values (v_uid, 'terms_and_privacy', p_policy_version)
  on conflict (profile_id, consent_type, policy_version) do nothing;

  insert into public.verification_requests (profile_id, requested_role, service_unit_id, troop_id, note)
  values (v_uid, p_requested_role, p_service_unit_id, p_troop_id, v_note)
  returning id into v_request_id;

  insert into public.service_unit_affiliations (profile_id, service_unit_id, verification_request_id)
  select v_uid, p_service_unit_id, v_request_id
  where not exists (
    select 1 from public.service_unit_affiliations
    where profile_id = v_uid and service_unit_id = p_service_unit_id and status in ('requested', 'approved')
  );

  if p_troop_id is not null then
    insert into public.troop_affiliations (profile_id, troop_id, verification_request_id)
    select v_uid, p_troop_id, v_request_id
    where not exists (
      select 1 from public.troop_affiliations
      where profile_id = v_uid and troop_id = p_troop_id and status in ('requested', 'approved')
    );
  end if;

  perform private.audit('verification.requested', 'verification_request', v_request_id,
    jsonb_build_object('requested_role', p_requested_role, 'service_unit_id', p_service_unit_id, 'troop_id', p_troop_id));

  return v_request_id;
end;
$$;

-- Withdraws your own pending request (for example, to fix a mistake).
create function public.withdraw_my_verification_request()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_request_id uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;

  update public.verification_requests set status = 'withdrawn', decided_at = now()
  where profile_id = v_uid and status = 'pending'
  returning id into v_request_id;

  if v_request_id is null then
    raise exception 'no_pending_request' using errcode = 'P0001';
  end if;

  update public.troop_affiliations set status = 'ended', decided_at = now()
  where verification_request_id = v_request_id and status = 'requested';
  update public.service_unit_affiliations set status = 'ended', decided_at = now()
  where verification_request_id = v_request_id and status = 'requested';

  perform private.audit('verification.withdrawn', 'verification_request', v_request_id);
end;
$$;

-- Deactivates your own account. Reactivation needs an administrator.
create function public.deactivate_my_account(p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;
  -- Suspended accounts stay suspended: deactivating must not erase an administrator's decision.
  update public.profiles
  set account_state = 'deactivated', state_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500)
  where id = v_uid and account_state in ('pending_verification', 'active');
  if not found then
    raise exception 'account_not_eligible' using errcode = 'P0001';
  end if;
  perform private.audit('account.deactivated_by_self', 'profile', v_uid);
end;
$$;

-- Records a deletion request and deactivates the account until an administrator completes it.
create function public.request_my_account_deletion(p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;
  update public.profiles
  set deletion_requested_at = coalesce(deletion_requested_at, now()),
      deletion_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500),
      account_state = case when account_state = 'suspended' then account_state else 'deactivated' end
  where id = v_uid;
  perform private.audit('account.deletion_requested', 'profile', v_uid);
end;
$$;

-- ---------------------------------------------------------------------------
-- Administration
-- ---------------------------------------------------------------------------

-- Verification queue with the details an administrator needs to confirm identity.
create function public.admin_list_verification_requests(p_status public.verification_status default 'pending')
returns table (
  id uuid,
  profile_id uuid,
  display_name text,
  email text,
  requested_role public.app_role,
  service_unit_id uuid,
  service_unit_name text,
  troop_id uuid,
  troop_number text,
  note text,
  status public.verification_status,
  decision_note text,
  created_at timestamptz,
  decided_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  return query
  select v.id, v.profile_id, p.display_name, u.email::text, v.requested_role, v.service_unit_id, s.name,
         v.troop_id, t.number, v.note, v.status, v.decision_note, v.created_at, v.decided_at
  from public.verification_requests v
  join public.profiles p on p.id = v.profile_id
  join auth.users u on u.id = v.profile_id
  join public.service_units s on s.id = v.service_unit_id
  left join public.troops t on t.id = v.troop_id
  where v.status = p_status
  order by v.created_at
  limit 200;
end;
$$;

-- Internal: grants a role after checking the granting administrator's authority.
create function private.grant_role_checked(
  p_profile_id uuid,
  p_role public.app_role,
  p_scope_type public.role_scope,
  p_scope_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid;
begin
  if not private.is_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if p_profile_id = v_uid then
    raise exception 'cannot_change_own_roles' using errcode = 'P0001';
  end if;
  if p_role in ('platform_admin', 'council_admin') and not private.is_platform_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if p_role in ('girl_member', 'guardian') and coalesce((private.setting('youth_access_enabled'))::boolean, false) is not true then
    raise exception 'youth_access_disabled' using errcode = 'P0001';
  end if;
  if p_scope_type = 'troop' and not exists (select 1 from public.troops where id = p_scope_id and archived_at is null) then
    raise exception 'invalid_scope' using errcode = 'P0001';
  end if;
  if p_scope_type = 'service_unit' and not exists (select 1 from public.service_units where id = p_scope_id and archived_at is null) then
    raise exception 'invalid_scope' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.profiles where id = p_profile_id) then
    raise exception 'invalid_profile' using errcode = 'P0001';
  end if;

  select id into v_id from public.role_assignments
  where profile_id = p_profile_id and role = p_role and scope_type = p_scope_type
    and scope_id is not distinct from p_scope_id and revoked_at is null;

  if v_id is null then
    insert into public.role_assignments (profile_id, role, scope_type, scope_id, granted_by)
    values (p_profile_id, p_role, p_scope_type, p_scope_id, v_uid)
    returning id into v_id;
    perform private.audit('role.granted', 'profile', p_profile_id,
      jsonb_build_object('role', p_role, 'scope_type', p_scope_type, 'scope_id', p_scope_id, 'assignment_id', v_id));
  end if;
  return v_id;
end;
$$;

-- Approves or rejects a verification request.
create function public.admin_decide_verification(p_request_id uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_request public.verification_requests%rowtype;
  v_note text := left(nullif(btrim(coalesce(p_note, '')), ''), 1000);
begin
  if not private.is_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  select * into v_request from public.verification_requests where id = p_request_id for update;
  if not found then
    raise exception 'request_not_found' using errcode = 'P0001';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'request_not_pending' using errcode = 'P0001';
  end if;
  if v_request.profile_id = v_uid then
    raise exception 'cannot_review_own_request' using errcode = 'P0001';
  end if;

  if p_approve then
    if v_request.requested_role = 'service_unit_coordinator' then
      perform private.grant_role_checked(v_request.profile_id, 'service_unit_coordinator', 'service_unit', v_request.service_unit_id);
    else
      perform private.grant_role_checked(v_request.profile_id, v_request.requested_role, 'troop', v_request.troop_id);
    end if;

    update public.service_unit_affiliations set status = 'approved', decided_by = v_uid, decided_at = now()
    where verification_request_id = p_request_id and status = 'requested';
    update public.troop_affiliations set status = 'approved', decided_by = v_uid, decided_at = now()
    where verification_request_id = p_request_id and status = 'requested';
    update public.profiles set account_state = 'active', state_reason = null
    where id = v_request.profile_id and account_state = 'pending_verification';
    update public.verification_requests set status = 'approved', decided_by = v_uid, decided_at = now(), decision_note = v_note
    where id = p_request_id;
    perform private.audit('verification.approved', 'verification_request', p_request_id,
      jsonb_build_object('profile_id', v_request.profile_id, 'role', v_request.requested_role));
  else
    if v_note is null then
      raise exception 'reason_required' using errcode = 'P0001';
    end if;
    update public.service_unit_affiliations set status = 'rejected', decided_by = v_uid, decided_at = now()
    where verification_request_id = p_request_id and status = 'requested';
    update public.troop_affiliations set status = 'rejected', decided_by = v_uid, decided_at = now()
    where verification_request_id = p_request_id and status = 'requested';
    update public.verification_requests set status = 'rejected', decided_by = v_uid, decided_at = now(), decision_note = v_note
    where id = p_request_id;
    perform private.audit('verification.rejected', 'verification_request', p_request_id,
      jsonb_build_object('profile_id', v_request.profile_id));
  end if;
end;
$$;

create function public.admin_grant_role(p_profile_id uuid, p_role public.app_role, p_scope_type public.role_scope, p_scope_id uuid default null)
returns uuid
language sql
security definer
set search_path = ''
as $$
  select private.grant_role_checked(p_profile_id, p_role, p_scope_type, p_scope_id);
$$;

create function public.admin_revoke_role(p_assignment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_assignment public.role_assignments%rowtype;
begin
  if not private.is_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  select * into v_assignment from public.role_assignments where id = p_assignment_id and revoked_at is null for update;
  if not found then
    raise exception 'assignment_not_found' using errcode = 'P0001';
  end if;
  if v_assignment.profile_id = v_uid then
    raise exception 'cannot_change_own_roles' using errcode = 'P0001';
  end if;
  if v_assignment.role in ('platform_admin', 'council_admin') and not private.is_platform_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  update public.role_assignments set revoked_at = now(), revoked_by = v_uid where id = p_assignment_id;
  perform private.audit('role.revoked', 'profile', v_assignment.profile_id,
    jsonb_build_object('role', v_assignment.role, 'assignment_id', p_assignment_id));
end;
$$;

-- Suspends, reactivates or deactivates someone else's account.
create function public.admin_set_account_state(p_profile_id uuid, p_state public.account_state, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_reason text := left(nullif(btrim(coalesce(p_reason, '')), ''), 500);
begin
  if not private.is_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;
  if p_profile_id = v_uid then
    raise exception 'cannot_change_own_state' using errcode = 'P0001';
  end if;
  if v_reason is null then
    raise exception 'reason_required' using errcode = 'P0001';
  end if;
  if p_state = 'pending_verification' then
    raise exception 'invalid_state' using errcode = 'P0001';
  end if;
  -- Only platform administrators can change other administrators' accounts.
  if exists (
    select 1 from public.role_assignments
    where profile_id = p_profile_id and role in ('platform_admin', 'council_admin') and revoked_at is null
  ) and not private.is_platform_admin() then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  update public.profiles set account_state = p_state, state_reason = v_reason where id = p_profile_id;
  if not found then
    raise exception 'invalid_profile' using errcode = 'P0001';
  end if;
  perform private.audit('account.state_changed', 'profile', p_profile_id, jsonb_build_object('state', p_state));
end;
$$;

-- One-time setup, run by the project owner in the Supabase SQL editor (never through the API):
--   select private.bootstrap_platform_admin('you@example.org');
-- It only works while no platform administrator exists.
create function private.bootstrap_platform_admin(p_email text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_profile_id uuid;
  v_assignment_id uuid;
begin
  if exists (select 1 from public.role_assignments where role = 'platform_admin' and revoked_at is null) then
    raise exception 'platform_admin_exists' using errcode = 'P0001',
      hint = 'Ask an existing platform administrator to grant roles instead.';
  end if;

  select id into v_profile_id from auth.users where lower(email) = lower(btrim(p_email));
  if v_profile_id is null then
    raise exception 'user_not_found' using errcode = 'P0001', hint = 'Sign up and confirm your email first.';
  end if;

  insert into public.role_assignments (profile_id, role, scope_type) values (v_profile_id, 'platform_admin', 'platform')
  returning id into v_assignment_id;
  insert into public.role_assignments (profile_id, role, scope_type) values (v_profile_id, 'council_admin', 'council');
  update public.profiles set account_state = 'active', state_reason = null where id = v_profile_id;
  insert into public.audit_logs (actor_id, action, target_type, target_id, metadata)
  values (null, 'role.bootstrap_platform_admin', 'profile', v_profile_id, '{}'::jsonb);
  return v_assignment_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Public contact form
-- ---------------------------------------------------------------------------
create function public.submit_contact_message(p_name text, p_email text, p_topic text, p_message text, p_website text default '')
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_message text := btrim(coalesce(p_message, ''));
  v_forwarded text := split_part(coalesce(nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for', ''), ',', 1);
begin
  -- Honeypot: people never see this field. Bots that fill it are dropped without storing anything.
  if coalesce(p_website, '') <> '' then
    return;
  end if;

  if char_length(v_name) not between 2 and 80 then
    raise exception 'invalid_name' using errcode = 'P0001';
  end if;
  if char_length(v_email) > 254 or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid_email' using errcode = 'P0001';
  end if;
  if p_topic not in ('general', 'pilot', 'accessibility', 'safety', 'bug') then
    raise exception 'invalid_topic' using errcode = 'P0001';
  end if;
  if char_length(v_message) not between 20 and 2000 then
    raise exception 'invalid_message' using errcode = 'P0001';
  end if;

  -- Limits per sender, per network address (stored only as a hash) and overall.
  perform private.check_rate_limit('contact:email:' || md5(v_email), 3, interval '1 hour');
  if btrim(v_forwarded) <> '' then
    perform private.check_rate_limit('contact:ip:' || md5(btrim(v_forwarded)), 10, interval '1 hour');
  end if;
  perform private.check_rate_limit('contact:all', 200, interval '1 hour');

  insert into public.contact_messages (name, email, topic, message) values (v_name, v_email, p_topic, v_message);
end;
$$;

-- ---------------------------------------------------------------------------
-- Function privileges: deny by default, then allow exactly what each role needs.
-- ---------------------------------------------------------------------------
revoke all on all functions in schema private from public, anon, authenticated;
grant execute on function
  private.current_account_state(),
  private.is_active(),
  private.has_role(public.app_role),
  private.has_scoped_role(public.app_role, public.role_scope, uuid),
  private.is_platform_admin(),
  private.is_admin()
to authenticated, service_role;

revoke all on function
  public.get_my_account(),
  public.list_affiliation_options(),
  public.submit_onboarding(text, public.app_role, uuid, uuid, text[], text, text),
  public.withdraw_my_verification_request(),
  public.deactivate_my_account(text),
  public.request_my_account_deletion(text),
  public.admin_list_verification_requests(public.verification_status),
  public.admin_decide_verification(uuid, boolean, text),
  public.admin_grant_role(uuid, public.app_role, public.role_scope, uuid),
  public.admin_revoke_role(uuid),
  public.admin_set_account_state(uuid, public.account_state, text),
  public.submit_contact_message(text, text, text, text, text)
from public, anon, authenticated;

grant execute on function
  public.get_my_account(),
  public.list_affiliation_options(),
  public.submit_onboarding(text, public.app_role, uuid, uuid, text[], text, text),
  public.withdraw_my_verification_request(),
  public.deactivate_my_account(text),
  public.request_my_account_deletion(text),
  public.admin_list_verification_requests(public.verification_status),
  public.admin_decide_verification(uuid, boolean, text),
  public.admin_grant_role(uuid, public.app_role, public.role_scope, uuid),
  public.admin_revoke_role(uuid),
  public.admin_set_account_state(uuid, public.account_state, text)
to authenticated;

grant execute on function public.submit_contact_message(text, text, text, text, text) to anon, authenticated;
